const item = $input.item.json;
const rawError = item && item.error;
const rawMessage = typeof rawError === 'string'
  ? rawError
  : (rawError && rawError.message) ? rawError.message : 'Unbekannter Fehler';

return [{
  json: {
    ...item,
    valid: false,
    errorMessage: 'Bei der Kommunikation mit dem lokalen Ollama-Modell ist ein Fehler aufgetreten. Bitte versuchen Sie es später erneut.\n\nDetails: ' + rawMessage
  }
}];

const parsed = $input.item.json;
const original = $('Teamdiagnose: Evidenz aufbereiten').first().json;
const leagueComparisonAvailable = false;

const teamDiagnosis = {
  simulated: false,
  dataAvailable: true,
  diagnosisCategory: parsed.diagnosisCategory,
  evidence: original.teamDiagnosisEvidence,
  leagueComparisonAvailable,
  leagueComparison: leagueComparisonAvailable
    ? parsed.leagueComparison
    : `Auf dieser Datengrundlage liegt kein belastbarer Vergleich zur Bundesliga-Konkurrenz vor: es liegen ausschliesslich Kennzahlen von '${original.club}' vor, keine Liga-Durchschnittswerte oder Kennzahlen anderer Vereine.`,
  hypotheses: parsed.hypotheses,
  counterHypotheses: parsed.counterHypotheses,
  mainProblem: parsed.mainProblem,
  uncertainties: parsed.uncertainties
};

return [{ json: { ...original, teamDiagnosis } }];

const item = $input.item.json;
const d = item.teamDiagnosis;
const errors = [];

if (!d || typeof d !== 'object') {
  errors.push('teamDiagnosis fehlt oder ist kein Objekt.');
} else {
  if (!Array.isArray(d.evidence) || d.evidence.length === 0) errors.push('teamDiagnosis.evidence fehlt oder ist leer.');
  if (typeof d.leagueComparisonAvailable !== 'boolean') errors.push('teamDiagnosis.leagueComparisonAvailable fehlt oder ist kein boolean.');
  if (typeof d.leagueComparison !== 'string' || !d.leagueComparison.trim()) errors.push('teamDiagnosis.leagueComparison fehlt.');
  if (!Array.isArray(d.hypotheses) || d.hypotheses.length === 0) errors.push('teamDiagnosis.hypotheses fehlt oder ist leer.');
  if (!Array.isArray(d.counterHypotheses)) errors.push('teamDiagnosis.counterHypotheses fehlt oder ist kein Array.');
  if (typeof d.mainProblem !== 'string' || !d.mainProblem.trim()) errors.push('teamDiagnosis.mainProblem fehlt.');
  if (!Array.isArray(d.uncertainties)) errors.push('teamDiagnosis.uncertainties fehlt oder ist kein Array.');
}

const valid = errors.length === 0;
return [{
  json: {
    ...item,
    valid,
    errorMessage: valid ? undefined : 'Die Teamdiagnose ist ungueltig und wird nicht als fachliche Grundlage verwendet.\n\n' + errors.join('\n')
  }
}];

const item = $input.item.json;
const d = item.teamDiagnosis;
const valid = !!d && d.diagnosisCategory !== 'no_data';

return [{
  json: {
    ...item,
    valid,
    errorMessage: valid
      ? undefined
      : `Fuer '${item.club}' liegen keine ausreichenden Analytics-Daten fuer eine Teamdiagnose vor. Eine Bedarfsermittlung (Spielerprofil) und Spielersuche werden deshalb nicht durchgefuehrt, statt auf einen beliebigen Positionspool zurueckzufallen. Bitte weitere Analytics-Daten fuer diesen Verein bereitstellen.\n\n${d && d.mainProblem ? d.mainProblem : ''}`
  }
}];

const item = $input.item.json;
if (item.valid === false) {
  throw new Error('[TEAM_ANALYSIS] ' + (item.errorMessage || 'Team analysieren ist fehlgeschlagen.'));
}
return [{ json: { ...item, status: 'success' } }];
